solution:
1. Qd1-c2? {- zugzwang}
1... Kb4-a3 2. Be3-c5#
but 1... Kb4-b5!

1.Sb7-c5 ! {- zugzwang}
   1...Kb4-a3  {(Kc3)}
       2.Qd1-b3 #
   1...Kb4-a5 {(Kb5, Kc4)}
       2.Qd1-a4 #

1.Rg4-f4 ? threat:
       2.Re7-e6 #
       2.Re7-e5 # {[B]}
       2.Re7-e4 # {display-departure-file}
       2.Re7-e8 # 
       2.Re7-f7 #
       2.Re7-g7 #
       2.Re7*h7 #
   1...Rf1*f4 2.Re7-f7 # {[A]}
   1...Bg3*f4 2.Re7-e5 # {[B]}
   1...Sg5-e4 2.Re7*e4 # {display-departure-file}
   1...Sg5-e6 2.Re7*e6 #
but 1...Sh4-f5 !

1.Sc2-e1 ? threat:
      2.Se1-d3 #
   1...Rf1*e1 2.Re7-e5 # {[B]}
   1...Bg3*e1 2.Re7-f7 # {[A]}
but 1...g6*h5 !

1.Sc2-a1 ? threat:
      2.Sa1-b3 #
but 1...Sg5-e4 !

1.Sc2-d4 ! threat:
       2.Sd4-b3 #
   1...Rf1-b1
       2.Re7-e5 # {[B]}
   1...Rf1-f4
       2.Re7-f7 # {[A]}
   1...Bg3-f4
       2.Re7-e5 # {[B]}
   1...Sg5-e4
       2.Sd4-e6 #

1.Rc3*c4 ? threat:
     2.Se8-d6 # {[A]}
but 1...Sd7-c5 ! {display-departure-file}

1.Bg2*e4 ? threat:
      2.Se8-d6 # {[A]}
but 1...g3-g2 !

1.Sd2*e4 ? threat:
      2.Se4-d6 # {display-departure-rank}
   1...c4*d3 2.Se8-d6 # {display-departure-rank} {(Thema B)}
but 1...Bd1-f3 ! {(Levman)}

1.Sd2*c4 ! threat:
       2.Sc4-d6 # {display-departure-file}
   1...e4*d3
       2.Se8-d6 # {display-departure-file} {[A] (Thema B)}
   1...Sd7-c5
       2.Rh6*b6 # {(Levman)}
   1...Sa6-c5 {(Sb8)}
       2.Se8-c7 #
   1...Sa6-c7
       2.Se8*c7 #
   1...Rb4*c4
       2.d3*c4 #

1.Qh3-h4 ? threat:
       2.Sg4-f2 # {[A]}
       2.Sg4-f6 # {[B]}
but 1...Sd5-f4 !

1.Bc1-e3 ? threat: 
      2.Sb5-d6 # {[C]}
but 1...d3-d2 !

1.Rf3-f2 ? threat:
      2.Qh3-f3 #
but 1...Sd1-e3 ! {display-departure-rank}

1.Rf3-f7 ? threat:
      2.Qh3-f3 #
but 1...Sd5-e3 ! {display-departure-rank}

1.Rf3-f5 ! threat:
       2.Qh3-f3 #
   1...Sd1-e3 {display-departure-rank}
       2.Sg4-f2 # {[A]}
   1...Sd5-e3 {display-departure-rank}
       2.Sg4-f6 # {[B]}
   1...Ke4*f5
       2.Sb5-d6 # {[C]}
   1...Sd5-f4
       2.Sg4-f6 #

1.Sc4-e5 ? threat:
       2.Qd2-b2 # {[A]}
       2.Qd2-b4 # {[B]}
   1...d6*e5 2.Re8-d8 #
but 1...Qh7*d3 ! {(Nietvelt)}

1.Sc4-b2 ? threat:
      2.Qd2-b4 #
but 1...Bf1*d3 ! {(Nietvelt)}
1.Ba3-b4 ? threat:
      2.Qd2-c3 #
but 1...Rh3*d3 ! {(Nietvelt)}


1.Sc4-a5 ! threat:
       2.Sa5*b3 #
   1...Bf1*d3
       2.Qd2-b2 # {[A]}
   1...Rh3*d3
       2.Qd2-b4 # {[B]}
   1...Qh7*d3
       2.Re8-e4 #

1.Sa3-c4 ? threat:
       2.Sc4*b6 #
but 1...Be5-d4 !

1.d2-d4 ? threat:
      2.Sb1*c3 # {[A]}
      2.Bb5-c4 # {[B]}
   1...Rh4*d4 2.Sb1*c3 #
   1...Be5*d4 2.Bb5-c4 #
but 1...Sf3-d2 ! {display-departure-file}

1.Rc6-c4 ? threat:
      2.Bb5-c6 #
   1...Sb3-d4 {display-departure-file} 2.Sb1*c3 {[A]}
but 1...Sf3-d4 ! {display-departure-file}

1.Rc6*c3 ? threat:
      2.Bb5-c6 #
   1...Sf3-d4 {display-departure-file} 2.Bb5-c4 {[B]}
but 1...Sb3-d4 ! {display-departure-file}

1.Rc6*b6 ! threat:
       2.Bb5-c6 #
   1...Sb3-d4  {display-departure-file}
       2.Sb1*c3 # {[A]}
   1...Sf3-d4 {display-departure-file}
       2.Bb5-c4 # {[B]}
   1...Rh4-c4 +
       2.Bb5*c4 #
